```java
private static long[] computeSegments(List<Long> cumulativeElapsed, long finishTimeMs) {
    long[] segments = new long[cumulativeElapsed.size() + 1];
    long previous = 0L;
    for (int i = 0; i < cumulativeElapsed.size(); i++) {
        long current = cumulativeElapsed.get(i);
        segments[i] = Math.subtractExact(current, previous);
        previous = current;
    }
    segments[cumulativeElapsed.size()] = Math.subtractExact(finishTimeMs, previous);
